CREATE OR REPLACE FUNCTION public.delete_empty_manpower_reporting_group(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform 1
  from public.manpower_reporting_groups
  where id = p_group_id
  for update;

  if not found then
    raise exception 'The reporting group was not found.';
  end if;

  if exists (
    select 1
    from public.manpower_entries
    where reporting_group_id = p_group_id
  ) then
    raise exception 'Only reporting groups without labor entries can be deleted.';
  end if;

  delete from public.manpower_reporting_groups
  where id = p_group_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_manpower_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
